"""Editorial orchard scenes; not supplier interviews or batch traceability."""
FIELD_NOTES = {
    "guava": ("把清脆，留在枝头慢慢养成。", "清晨的果园还带着露水，果农沿着树行查看新梢和枝叶，把过密枝条整理开，让叶间留出光与风。小果挂稳以后，再逐个观察形状和表皮，照顾那些藏在叶子背后的果实。", "采收时，果农一手托住果实，一手处理果柄，不让芭乐直接跌进筐底。摘下的果实先放入垫着软衬的浅筐，按外观与熟度分开；清脆的、偏软的，各自走向合适的食用窗口。"),
    "mango": ("一颗芒果，先在树上过完漫长的夏天。", "在这个果园场景里，日常照料从巡园开始：看看枝条是否承得住果实，看看叶片之间是否留有空气。果农不急着把满树的果都采走，而是一次次回到同一棵树下，观察果肩和转色。", "到了采收的早晨，手掌先托稳果身，再处理果柄，果实轻放入筐。回到分选台，按成熟程度和外观归组，垫好缓冲层；同一树上的芒果，也可以分几次走向餐桌。"),
    "banana": ("从层层蕉叶，到一梳温柔的甜。", "一阵风翻起宽大的蕉叶，果农顺着田埂查看蕉株的状态，整理周边环境，留意果穗的生长。细小的观察日复一日，等原本瘦小的蕉指慢慢变得饱满。", "收获的场景需要两个人配合：一人稳住果穗，另一人处理采收，避免整穗落地。随后轻放、分梳、检查表皮，在分选台上把运输批次与更适合即食的批次分开。"),
    "pineapple": ("低低的叶丛，也藏着一段生长的耐心。", "果农穿过菠萝田的窄道，查看叶丛间的果实，整理田间杂草和排水通道。每一颗菠萝都在贴近土地的地方慢慢长大，颜色与饱满度成为巡田时反复观察的细节。", "采收时戴上手套，避开叶缘，一手扶稳果体再处理果柄。采下的果实不随手抛堆，而是轻放、分级，包装时给果冠与果身留出空间，让这一颗土地里的甜走得从容。"),
    "papaya": ("沿着树干，等一抹橙色慢慢浮出来。", "木瓜沿树干一层层生长，果农巡园时查看叶片与果体状态，也检查地面的排水。不同位置的果实有自己的节奏，今天观察到的转色，会成为下一次采收的线索。", "采收者靠近树干，托稳果实再取下，尽量减少表皮摩擦。分选台上，软熟批次被单独标识，缓冲材料隔开彼此，让已经柔软的果肉少经历一次挤压。"),
    "dragon": ("夜里开的花，白天照料的果。", "果农沿着支架查看枝条，整理生长方向，记录开花和坐果的变化。茎条间的一点红色逐渐鲜明，巡园的目光开始更多停留在果皮和鳞片上。", "采收前先看外观与完整度，再托住果体处理连接处。果实之间垫上隔层，避免鳞片互相摩擦；鲜明的颜色之外，分选台还会仔细检查不容易看见的碰伤。"),
    "coconut": ("海风经过的地方，有人照料这一片椰林。", "椰林下，日常照料从查看树势和地面环境开始。抬头能看到不同生长阶段的果串，果农按批次观察，给后续采收留下一份清楚的安排。", "采收由有经验的人员使用合适工具完成，在地面接应、归拢后再分选。清理外层、检查完整度、按用途归组，把饮用椰水与品尝椰肉的不同期待分别照顾。"),
    "passion": ("藤架下的一点阴凉，养出浓烈的香。", "果农沿藤架查看新梢与果实，整理枝蔓，让藤架之间留有通行和通风空间。小果藏在叶影里，巡园时需要拨开枝叶，耐心看看颜色的变化。", "采收时先检查果壳完整度，把合适的果实轻放入筐。裂口、渗漏和异常状态在分选时被逐个检查；完整的果壳继续护着果浆，直到被带回厨房的那一刻。"),
    "durian": ("浓香之前，是果园里一天天的守候。", "在榴莲园的场景里，果农观察树势、枝条和果实状态，管理树下环境，也为作业区域留出安全空间。厚厚的果壳之外，还有许多不在商品照片里的日常照料。", "收获由有经验的人员按批次安排，避免果实与人员受到坠落伤害。到分选台后，检查果壳和外观状态，按熟度与规格标识；运输时为坚硬的外壳安排隔离与缓冲。"),
    "mangosteen": ("紫色果壳，是树荫里慢慢写成的一封信。", "山竹果藏在浓密树冠间，果农观察叶片与果体状态，整理园间环境。原本青绿的果皮逐渐变化，采收计划也跟着这些细小的变化一点点靠近。", "采收者轻取果实，避免果壳落地碰伤，保留完整的外观。分选时检查果蒂与表皮，把异常裂损挑出；托盘里的隔层，替这颗看似结实的果实挡住路上的磕碰。"),
    "rambutan": ("把枝头的红，轻轻放进果筐。", "果农在树行间观察果串与枝叶，让果园保持便于照料的空间。带着柔软毛刺的小果渐渐转色，一整串里也会有不同的成熟节奏。", "采收时托稳果串再处理枝柄，随后轻放归筐，避免互相挤压。分选台查看外观、完整度和熟度，包装不紧紧压住果皮，让这份鲜明的热带色彩保留舒展的样子。"),
    "avocado": ("从树上的青绿，到餐桌上的柔软。", "牛油果园里，果农查看枝叶和挂果状态，按批次观察果形与生长变化。采收安排与后续成熟管理相互衔接，树上的等待和到货后的等待，是故事的两段。", "采收时托住果实、轻放入筐，避免坚硬外表掩盖了内部碰伤。分选与包装按实际熟度管理，收到后再结合状态安排食用，让从青绿到柔软的变化发生在合适的时候。"),
    "starfruit": ("树荫里挂着的，是还没切开的星星。", "杨桃在枝叶间渐渐饱满，果农观察果体与果棱，整理树冠周边环境。每次巡园都看看表皮变化，等待适合这一批果实的采收时机。", "采收者托住果身，不紧捏突出的果棱，取下后轻轻放进浅筐。分选时检查果棱碰伤，用缓冲材料隔开果实，尽量把那道清楚的星形轮廓留到切开的时候。"),
    "lychee": ("一簇红色，装着短暂而明亮的季节。", "荔枝园里，果农查看枝梢与成串的果实，记录转色和饱满度。绿叶之间的红色越来越密，采收与包装的安排也逐渐紧凑起来。", "采收时按果串轻取，再检查果壳与果柄，减少反复翻动。分选后的批次及时包装，并按实际条件安排运输；季节短，所以更需要把每一次轻拿轻放做好。"),
}
